// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 n) public {
        n = bound(n, 2, 8); // at least two airdrop attempts by the same caller
        Caller caller = new Caller(c);
        // first airDrop succeeds on both versions (balance 0 -> 20);
        // subsequent attempts must fail on the reference, succeed on the mutant.
        try caller.go(n) { /* may revert inside on reference */ } catch {}
        assertTrue(c.tokenBalance(address(caller)) <= 20);
    }
}

contract Caller {
    ModifierEntrancy c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function go(uint256 n) external {
        for (uint256 i = 0; i < n; i++) {
            c.airDrop();
        }
    }
}
